public class SignupValidator {

    public static void validate(String name, String email, int age) throws RuleViolation {
        if (name == null || name.trim().isEmpty()) {
            throw new RuleViolation("name", "must not be blank");
        }
        if (email == null || !email.contains("@")) {
            throw new RuleViolation("email", "must contain @");
        }
        if (age < 13) {
            throw new RuleViolation("age", "must be at least 13");
        }
    }
}

