import java.util.ArrayList;
import java.util.List;

public class SignupBatchProcessor {

    private final List<String> failures = new ArrayList<>();
    private final List<String> failedFields = new ArrayList<>();
    private int accepted;

    public void submit(String name, String email, int age) {
        try {
            SignupValidator.validate(name, email, age);
            accepted++;
        } catch (RuleViolation e) {
            failures.add(e.getMessage());
            failedFields.add(e.getField());
        }
    }

    public int accepted() {
        return accepted;
    }

    public List<String> failures() {
        return failures;
    }

    public List<String> failedFields() {
        return failedFields;
    }

    public String report() {
        return "accepted=" + accepted + " rejected=" + failures.size();
    }
}

