public class SignupBatchProcessorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static String violation(String name, String email, int age) {
        try {
            SignupValidator.validate(name, email, age);
            return "accepted";
        } catch (RuleViolation e) {
            return e.getField() + "/" + e.getMessage();
        }
    }

    public static void main(String[] args) {
        check("a valid sign-up is accepted", "accepted", violation("ana", "ana@mail.com", 30));
        check("a blank name is rejected", "name/name: must not be blank",
              violation("   ", "ana@mail.com", 30));
        check("a null name is rejected", "name/name: must not be blank",
              violation(null, "ana@mail.com", 30));
        check("a bad email is rejected", "email/email: must contain @",
              violation("ana", "ana.mail.com", 30));
        check("age is checked last", "age/age: must be at least 13",
              violation("ana", "ana@mail.com", 12));
        check("only the first broken rule is reported", "name/name: must not be blank",
              violation("", "nope", 4));
        check("exactly 13 is old enough", "accepted", violation("bo", "bo@mail.com", 13));

        SignupBatchProcessor batch = new SignupBatchProcessor();
        String outcome;
        try {
            batch.submit("ana", "ana@mail.com", 30);
            batch.submit("bo", "bo.mail.com", 22);
            batch.submit("", "cy@mail.com", 40);
            batch.submit("dee", "dee@mail.com", 9);
            outcome = "kept going";
        } catch (Exception e) {
            outcome = e.getClass().getSimpleName();
        }
        check("submit never throws", "kept going", outcome);
        check("accepted count", 1, batch.accepted());
        check("failure messages",
              "[email: must contain @, name: must not be blank, age: must be at least 13]",
              String.valueOf(batch.failures()));
        check("failed fields", "[email, name, age]", String.valueOf(batch.failedFields()));
        check("report", "accepted=1 rejected=3", batch.report());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

